import React, { useState, useEffect } from 'react';
import axios from 'axios';

const SearchBar = ({ onMovieSelect }) => {
    const [query, setQuery] = useState('');
    const [results, setResults] = useState([]);
    const [isSearching, setIsSearching] = useState(false);

    // Kendi TMDB API Anahtarını buraya yazmalısın
    const TMDB_API_KEY = 'SENIN_TMDB_API_ANAHTARIN';

    useEffect(() => {
        // Kullanıcı yazmayı bıraktıktan yarım saniye sonra arama yapması için "Debounce" mantığı
        const delayDebounceFn = setTimeout(async () => {
            if (query.length > 2) {
                setIsSearching(true);
                try {
                    const response = await axios.get(
                        `https://api.themoviedb.org/3/search/movie?api_key=${TMDB_API_KEY}&language=tr-TR&query=${query}&page=1`
                    );
                    setResults(response.data.results.slice(0, 5)); // Sadece ilk 5 sonucu göster
                } catch (error) {
                    console.error("TMDB'de film aranırken hata oluştu:", error);
                } finally {
                    setIsSearching(false);
                }
            } else {
                setResults([]);
            }
        }, 500);

        return () => clearTimeout(delayDebounceFn);
    }, [query, TMDB_API_KEY]);

    const handleSelect = (movie) => {
        onMovieSelect(movie);
        setQuery(''); // Seçim yapıldıktan sonra arama çubuğunu temizle
        setResults([]); // Arama sonuç listesini gizle
    };

    return (
        <div style={{ position: 'relative', marginBottom: '20px' }}>
            <input
                type="text"
                placeholder="Örnek: Yüzüklerin Efendisi..."
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                style={{
                    width: '100%',
                    padding: '10px',
                    borderRadius: '5px',
                    border: '1px solid #ccc',
                    boxSizing: 'border-box'
                }}
            />
            {isSearching && <p style={{ fontSize: '12px', color: '#888' }}>Aranıyor...</p>}

            {results.length > 0 && (
                <ul style={{
                    position: 'absolute',
                    top: '100%',
                    left: 0,
                    right: 0,
                    backgroundColor: 'white',
                    border: '1px solid #ccc',
                    borderRadius: '5px',
                    listStyle: 'none',
                    padding: 0,
                    margin: 0,
                    maxHeight: '200px',
                    overflowY: 'auto',
                    zIndex: 1000
                }}>
                    {results.map((movie) => (
                        <li
                            key={movie.id}
                            onClick={() => handleSelect(movie)}
                            style={{
                                padding: '10px',
                                borderBottom: '1px solid #eee',
                                cursor: 'pointer'
                            }}
                        >
                            {movie.title} <span style={{ fontSize: '12px', color: '#888' }}>({movie.release_date?.substring(0, 4)})</span>
                        </li>
                    ))}
                </ul>
            )}
        </div>
    );
};

export default SearchBar;
